            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each character to their action.', 'match_pairs' => [['left' => 'The wolf', 'right' => 'Swallowed six kids whole'], ['left' => 'The youngest kid', 'right' => 'Hid in the clock-case'], ['left' => 'The mother', 'right' => 'Sewed big stones into the wolf\'s belly']]],
