            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each character to their part in the story.', 'match_pairs' => [['left' => 'The little gray man', 'right' => 'Rewarded Dummling\'s kindness with luck'], ['left' => 'The princess', 'right' => 'Laughed at the stuck-together train'], ['left' => 'The king', 'right' => 'Kept inventing harder tasks']]],
