            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'Why did the gray-haired man grant the ship that sails on land and water?', 'option_a' => 'Because Dummling was kind to him long ago', 'option_b' => 'Because Dummling paid gold for it', 'option_c' => 'To punish the greedy king', 'option_d' => 'So he could marry the princess himself', 'correct_option' => 'a'],
            ['section' => 'Comprehension', 'type' => 'identification', 'question_text' => 'Which family member gave each brother a cake and wine before woodcutting?', 'acceptable_answers' => ['mother', 'his mother', 'their mother']],
