            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each vision to its match.', 'match_pairs' => [['left' => 'The first match', 'right' => 'Showed a warm iron stove'], ['left' => 'The second match', 'right' => 'Revealed a roast goose at the table'], ['left' => 'The whole bundle', 'right' => 'Brought back her beloved grandmother']]],
